public async Task<string> ProcessUserTurnAsync(
    string sessionId,
    string tenantId,
    string userMessage,
    CancellationToken ct)
{
    using (_logger.BeginScope(new Dictionary<string, object>
    {
        ["SessionId"] = sessionId,
        ["TenantId"] = tenantId,
        ["ConversationTimestamp"] = DateTimeOffset.UtcNow
    }))
    {
        _logger.LogInformation("Beginning user conversation turn.");

        // All logs emitted inside retrieval, tools, and model calls automatically inherit SessionId & TenantId
        var context = await _retriever.RetrieveAsync(userMessage, ct);
        var answer = await _agent.ExecuteStepAsync(userMessage, context, ct);

        _logger.LogInformation("Successfully finished conversation turn.");
        return answer;
    }
}
